/// Every §27 namespace behind one accessor (§27.2 rule 4).
///
/// `client.management.users` and `client.users` are the same handle. This exists for callers
/// who prefer the management surface not to be mixed in with §1's methods when reading a call
/// site; rule 4 requires the two forms be equivalent, and they are because these delegate to
/// the same initializer the direct accessors use.
public struct ManagementApi: Sendable {
    private let client: AxiamClient
    private let scope: CallScope

    init(client: AxiamClient, scope: CallScope) {
        self.client = client
        self.scope = scope
    }

    /// Organizations an SDK client may read and configure. Creation and deletion are outside
    /// the SDK boundary (§27.0).
    public var organizations: OrganizationsApi {
        OrganizationsApi(client: client, scope: scope)
    }

    /// Tenants within an organization -- the isolation boundary every other namespace is scoped
    /// to.
    public var tenants: TenantsApi {
        TenantsApi(client: client, scope: scope)
    }

    /// Users within the client's tenant, and the administrative side of their second factor and
    /// lockout state.
    public var users: UsersApi {
        UsersApi(client: client, scope: scope)
    }

    /// Named collections of users. Roles assigned to a group are inherited by every member.
    public var groups: GroupsApi {
        GroupsApi(client: client, scope: scope)
    }

    /// Roles, their permission sets, and their assignment to users and groups.
    public var roles: RolesApi {
        RolesApi(client: client, scope: scope)
    }

    /// Permissions -- an action on a resource, optionally narrowed by a scope.
    public var permissions: PermissionsApi {
        PermissionsApi(client: client, scope: scope)
    }

    /// The resource hierarchy role assignments cascade down.
    public var resources: ResourcesApi {
        ResourcesApi(client: client, scope: scope)
    }

    /// Sub-resource granularity, always addressed under their resource.
    public var scopes: ScopesApi {
        ScopesApi(client: client, scope: scope)
    }

    /// Machine identities, their secrets, and the certificate a device-bound one authenticates
    /// with.
    public var serviceAccounts: ServiceAccountsApi {
        ServiceAccountsApi(client: client, scope: scope)
    }

    /// End-entity X.509 certificates -- the ones issued to users, services and IoT devices.
    public var certificates: CertificatesApi {
        CertificatesApi(client: client, scope: scope)
    }

    /// Organization CAs and the per-tenant signing CAs chained beneath them.
    public var caCertificates: CaCertificatesApi {
        CaCertificatesApi(client: client, scope: scope)
    }

    /// OpenPGP keys used for audit signing and encrypted data export.
    public var pgpKeys: PgpKeysApi {
        PgpKeysApi(client: client, scope: scope)
    }

    /// Outbound event notifications. Delivery signatures are verified with the §13 helper,
    /// which this namespace configures.
    public var webhooks: WebhooksApi {
        WebhooksApi(client: client, scope: scope)
    }

    /// Registered OAuth2/OIDC clients -- the registration half of what §12, §21 and §26 then
    /// speak to.
    public var oauth2Clients: Oauth2ClientsApi {
        Oauth2ClientsApi(client: client, scope: scope)
    }

    /// Upstream IdP configuration and the per-user links it produces.
    public var federation: FederationApi {
        FederationApi(client: client, scope: scope)
    }

    /// Which events raise a notification, and to whom.
    public var notificationRules: NotificationRulesApi {
        NotificationRulesApi(client: client, scope: scope)
    }

    /// Transactional-mail transport, configurable at organization level and overridable per
    /// tenant.
    public var emailConfig: EmailConfigApi {
        EmailConfigApi(client: client, scope: scope)
    }

    /// Effective settings, and the organization/tenant layers they resolve from.
    public var settings: SettingsApi {
        SettingsApi(client: client, scope: scope)
    }

    /// Bearer tokens for the SCIM 2.0 provisioning endpoint.
    public var scimTokens: ScimTokensApi {
        ScimTokensApi(client: client, scope: scope)
    }

    /// Registration of §22 AMQP extension actors -- the admin surface §22.9 describes, which no
    /// SDK could previously reach.
    public var reactors: ReactorsApi {
        ReactorsApi(client: client, scope: scope)
    }

    /// Per-tenant attestation policy governing the §24 ceremonies, and the compliance report
    /// over it.
    public var webauthnPolicy: WebauthnPolicyApi {
        WebauthnPolicyApi(client: client, scope: scope)
    }

    /// Append-only audit log, read-only by construction.
    public var audit: AuditApi {
        AuditApi(client: client, scope: scope)
    }

    /// GDPR self-service: the authenticated account's own export and erasure. Scoped to the
    /// caller, never to another user.
    public var privacy: PrivacyApi {
        PrivacyApi(client: client, scope: scope)
    }

    /// Deployment-level probes and FIDO metadata state. Unauthenticated where the server leaves
    /// them so.
    public var platform: PlatformApi {
        PlatformApi(client: client, scope: scope)
    }

    /// Declarative management — plan and apply a §27.6 manifest.
    public var manifest: ManifestApi {
        ManifestApi(client: client, scope: scope)
    }
}

// §27.2/§27.3: the namespace handles sit directly on the client —
// `client.serviceAccounts.rotateSecret(id)` is §27.3's Swift row verbatim. `client.management`
// above reaches the same handles behind one accessor.
//
// `nonisolated`, so reaching a handle is not itself an actor hop: `try await
// client.roles.list()` needs the one `await` the operation earns, not two. Nothing here touches
// isolated state — a handle is the client reference plus an empty scope, which is why acquiring
// one can perform no I/O (§27.2 rule 1).
